def main(argv):
    out = Path(argv[2]) if len(argv) > 2 else Path("/app/out")
    out.mkdir(parents=True, exist_ok=True)
    for name, text in RECORDS.items():
        (out / name).write_text(text, encoding="utf-8")
    return 0


